require("nvchad.configs.lspconfig").defaults()

vim.lsp.config("opencl_ls", {
  filetypes = { "cl", "lisp" }, -- lisp, because nvim-lspconfig treats .cl files as a lisp
})

-- OpenBMC / embedded C++ support -------------------------------------------
--
-- The compile database is generated by BitBake/Meson under
--   <openbmc>/build/<machine>/tmp/work/.../bmcweb-*/compile_commands.json
-- and published next to the sources by
--   ~/extraSpace/embedded/clangd/gen_compile_db.py
-- Run that script after `devtool build bmcweb`; clangd then finds the database
-- automatically in a parent directory of the edited file.
--
-- --query-driver lets clangd ask a compiler for its target/system includes.
-- Without it, clangd cannot find libstdc++ or Boost headers for the cross
-- build.  The glob covers the Yocto SDK toolchain used by the compile
-- commands, so it keeps working when a new build directory is created.  The
-- /usr/bin/* entry is the fallback for files edited outside a built tree
-- (clangd then uses the host compiler and the host Boost headers).
local openbmc_root = vim.fs.joinpath(vim.fn.expand "~", "extraSpace", "embedded", "openbmc")
local query_driver = table.concat({
  "/usr/bin/*",
  openbmc_root .. "/build/*/tmp/work/*/*/*/recipe-sysroot-native/usr/bin/*/*-g++",
  openbmc_root .. "/build/*/tmp/work/*/*/*/recipe-sysroot-native/usr/bin/*/*-gcc",
}, ",")

vim.lsp.config("clangd", {
  cmd = {
    "clangd",
    "--header-insertion=never",
    "--background-index",
    "--completion-style=detailed",
    "--query-driver=" .. query_driver,
  },
})

vim.lsp.config("dockerls", {
  cmd = { "docker-language-server", "start", "--stdio" },
})

local servers = { "html", "cssls", "clangd", "opencl_ls", "stylua", "neocmake", "dockerls", "shuck" }
vim.lsp.enable(servers)

-- read :h vim.lsp.config for changing options of lsp servers
